-- Guards the shape of the data generated by UpdateForeverBiS.py (schema 3: one source per data file, each holding
-- schema 2 phases and lists): the model indexes it blindly.
local VALID_KINDS = { quest = true, profession = true, dungeon = true, world = true, unknown = true }
local Toc = dofile("tests/support/toc.lua")

-- Data files in the .toc, as { path, source id }; the id is the file name after "ForeverBiS_Data_", lowercased.
local function dataFiles()
    local files = {}
    for _, path in ipairs(Toc.files()) do
        local name = path:match("^ForeverBiS_Data_(.+)%.lua$")
        if name then
            files[#files + 1] = { path = path, id = string.lower(name) }
        end
    end
    return files
end

describe("ForeverBiS_Data", function()
    setup(function()
        local paths = {}
        for _, file in ipairs(dataFiles()) do
            paths[#paths + 1] = file.path
        end
        WowStub.loadFiles(paths)
    end)

    local function eachSource(visit)
        for id, source in pairs(ForeverBiSData.sources) do
            visit(id, source)
        end
    end

    local function eachPhase(visit)
        eachSource(function(id, source)
            for route, list in pairs(source.lists) do
                for phaseId, phase in pairs(list.phases) do
                    visit(id .. ":" .. route, phaseId, phase)
                end
            end
        end)
    end

    it("ships at least the ForeverChanges file, and no unlisted data files", function()
        local files = dataFiles()
        assert.is_true(#files > 0)
        assert.are.equal("ForeverBiS_Data_ForeverChanges.lua", files[1].path)
        local handle = io.popen('ls ForeverBiS | grep "^ForeverBiS_Data_"')
        local onDisk = {}
        for name in handle:lines() do
            onDisk[#onDisk + 1] = name
        end
        handle:close()
        -- KamiLabs is generated but not shipped yet: files on disk may exceed the .toc, never the reverse.
        local listed = {}
        for _, name in ipairs(onDisk) do
            listed[name] = true
        end
        for _, file in ipairs(files) do
            assert.is_true(listed[file.path], file.path .. " is in the .toc but missing")
        end
    end)

    it("defines schema 3 with one source per data file and no legacy globals", function()
        assert.are.equal(3, ForeverBiSData.schema)
        for _, file in ipairs(dataFiles()) do
            assert.is_table(ForeverBiSData.sources[file.id], file.path .. " must register source " .. file.id)
        end
        assert.is_nil(ForeverBiSData.phases)
        assert.is_nil(ForeverBiSData.lists)
    end)

    it("describes every source with a label, an order, a url and schema 2 phases and lists", function()
        local orders = {}
        eachSource(function(id, source)
            assert.is_string(source.label, id)
            assert.is_true(source.label ~= "", id)
            assert.is_number(source.order, id)
            assert.is_nil(orders[source.order], id .. " repeats order " .. tostring(source.order))
            orders[source.order] = true
            assert.is_string(source.url, id)
            assert.is_truthy(source.url:match("^https://"), id)
            assert.is_table(source.phases, id)
            assert.is_table(source.lists, id)
        end)
    end)

    it("orders phases oldest first with unique ids", function()
        local total = 0
        eachSource(function(id, source)
            local seen, previousLevel = {}, nil
            for _, phase in ipairs(source.phases) do
                total = total + 1
                assert.is_string(phase.id, id)
                assert.is_string(phase.label, id)
                assert.is_nil(seen[phase.id], id .. " duplicate phase " .. phase.id)
                seen[phase.id] = true
                if phase.level then
                    assert.is_number(phase.level)
                    assert.is_true(previousLevel == nil or phase.level >= previousLevel, id .. " phases out of order")
                    previousLevel = phase.level
                end
            end
        end)
        assert.is_true(total > 0)
    end)

    it("gives every list a label and phases that are declared by its source", function()
        eachSource(function(id, source)
            local declared = {}
            for _, phase in ipairs(source.phases) do
                declared[phase.id] = true
            end
            for route, list in pairs(source.lists) do
                assert.is_string(list.label, id .. ":" .. route)
                assert.is_true(next(list.phases) ~= nil, route .. " has no phase")
                for phaseId in pairs(list.phases) do
                    assert.is_true(declared[phaseId], route .. " uses undeclared phase " .. tostring(phaseId))
                end
            end
        end)
    end)

    it("has a title and at least one slot for every phase", function()
        eachPhase(function(route, phaseId, phase)
            assert.is_string(phase.title, route .. "/" .. phaseId)
            assert.is_true(#phase.slots > 0, route .. "/" .. phaseId .. " has no slots")
        end)
    end)

    it("gives every slot a name and ranked items with a structured source", function()
        eachPhase(function(route, phaseId, phase)
            for _, slot in ipairs(phase.slots) do
                local where = route .. "/" .. phaseId .. "/" .. tostring(slot.slot)
                assert.is_string(slot.slot, where)
                assert.is_true(#slot.items > 0, where .. " has no items")
                for _, item in ipairs(slot.items) do
                    assert.is_string(item.name, where)
                    assert.is_true(item.id == nil or type(item.id) == "number", where .. " " .. item.name)
                    assert.is_table(item.source, where .. " " .. item.name)
                    assert.is_true(VALID_KINDS[item.source.kind], where .. " bad kind " .. tostring(item.source.kind))
                    assert.is_string(item.source.text, where .. " " .. item.name)
                end
            end
        end)
    end)

    it("stores enchants as {effect, spell, source[, formulaId]}", function()
        local total = 0
        eachPhase(function(route, _, phase)
            for _, slot in ipairs(phase.slots) do
                if slot.enchants ~= nil then
                    assert.is_true(#slot.enchants > 0, route .. "/" .. slot.slot .. " has an empty enchants table")
                end
                for _, enchant in ipairs(slot.enchants or {}) do
                    local where = route .. "/" .. slot.slot
                    total = total + 1
                    assert.is_string(enchant.effect, where)
                    assert.is_true(enchant.effect ~= "", where .. " has an empty effect")
                    assert.is_string(enchant.spell, where)
                    assert.is_string(enchant.source, where)
                    assert.is_true(enchant.formulaId == nil or type(enchant.formulaId) == "number", where)
                end
            end
        end)
        assert.is_true(total > 0, "no enchants found in any list")
    end)
end)
